-- Execute integralmente no SQL Editor do Supabase.
create table public.usuarios (id uuid primary key references auth.users(id) on delete cascade, nome text not null, email text not null unique, perfil text not null default 'cliente' check (perfil in ('cliente','admin')), criado_em timestamptz not null default now());
create table public.produtos (id uuid primary key default gen_random_uuid(), nome text not null, descricao text not null, preco numeric(10,2) not null check(preco>=0), foto_url text not null, categoria text not null, ativo boolean not null default true, criado_em timestamptz not null default now());
create table public.pedidos (id uuid primary key default gen_random_uuid(), usuario_id uuid not null references public.usuarios(id), endereco text not null, status text not null default 'recebido' check(status in ('recebido','em_preparo','saiu','concluido')), total numeric(10,2) not null check(total>=0), criado_em timestamptz not null default now());
create table public.itens_pedido (id uuid primary key default gen_random_uuid(), pedido_id uuid not null references public.pedidos(id) on delete cascade, produto_id uuid not null references public.produtos(id), quantidade integer not null check(quantidade>0), preco_unitario numeric(10,2) not null check(preco_unitario>=0));
create or replace function public.criar_perfil() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.usuarios(id,nome,email) values(new.id,coalesce(new.raw_user_meta_data->>'nome','Cliente'),new.email); return new; end; $$;
create trigger ao_criar_usuario after insert on auth.users for each row execute function public.criar_perfil();
alter table public.usuarios enable row level security; alter table public.produtos enable row level security; alter table public.pedidos enable row level security; alter table public.itens_pedido enable row level security;
create function public.eh_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.usuarios where id=auth.uid() and perfil='admin') $$;
create policy "catálogo público" on public.produtos for select using (ativo or public.eh_admin()); create policy "admin produtos" on public.produtos for all using (public.eh_admin()) with check(public.eh_admin());
create policy "ler próprio perfil" on public.usuarios for select using (id=auth.uid() or public.eh_admin());
create policy "cliente cria pedido" on public.pedidos for insert with check(usuario_id=auth.uid()); create policy "cliente lê pedidos" on public.pedidos for select using(usuario_id=auth.uid() or public.eh_admin()); create policy "admin atualiza pedidos" on public.pedidos for update using(public.eh_admin());
create policy "cliente cria itens próprios" on public.itens_pedido for insert with check(exists(select 1 from public.pedidos p where p.id=pedido_id and p.usuario_id=auth.uid())); create policy "ler itens próprios" on public.itens_pedido for select using(exists(select 1 from public.pedidos p where p.id=pedido_id and (p.usuario_id=auth.uid() or public.eh_admin())));
